// ══════════════════════════════════════════════════════════════
//  FONCTION DE SÉLECTION PAR THÈME ET LANGUE
// ══════════════════════════════════════════════════════════════

function getVersetsParTheme(theme, langue) {
  const lang = (langue || 'fr').toLowerCase();
  switch(theme) {
    case 'amour':
      return (lang === 'en') ? AMOUR_EN : AMOUR_FR;
    case 'travail':
      return (lang === 'en') ? TRAVAIL_EN : TRAVAIL_FR;
    case 'famille':
      return (lang === 'en') ? FAMILLE_EN : FAMILLE_FR;
    case 'amitie':
      return (lang === 'en') ? AMITIE_EN : AMITIE_FR;
    default:
      return (lang === 'en') ? [...AMOUR_EN, ...TRAVAIL_EN, ...FAMILLE_EN, ...AMITIE_EN]
                             : [...AMOUR_FR, ...TRAVAIL_FR, ...FAMILLE_FR, ...AMITIE_FR];
  }
}
